    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260822094107_AddBooksAndReadingLogs') THEN
    PERFORM setval(
        pg_get_serial_sequence('"Badges"', 'Id'),
        GREATEST(
            (SELECT MAX("Id") FROM "Badges") + 1,
            nextval(pg_get_serial_sequence('"Badges"', 'Id'))),
