DO $EF$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM "__EFMigrationsHistory" WHERE "MigrationId" = '20260823130510_AddNormalizedNameColumn') THEN

        DELETE FROM "Habits" h
        USING (
            SELECT "Id",
                   ROW_NUMBER() OVER (PARTITION BY "UserId", UPPER("Name") ORDER BY "Id") AS rn
            FROM "Habits"
        ) ranked
        WHERE h."Id" = ranked."Id" AND ranked.rn > 1;

    END IF;
END $EF$;

DO $EF$
